// This file is generated by AI.

// 图标层的校验: 静态导入的 SVG 在包里真实存在, 且类型联合、运行期清单与导入数量三者一致。

import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vitest';

import { ICON_NAMES, ICON_SVG } from '../src/ui/icons';

const editorRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const iconsDir = join(editorRoot, '..', 'node_modules', '@fluentui', 'svg-icons', 'icons');
const source = readFileSync(join(editorRoot, 'src', 'ui', 'icons.ts'), 'utf8');

/** 提取源码里所有 `@fluentui/svg-icons/icons/<file>?raw` 引用 (必须读源码而非运行期对象, 才能校验导入的文件真的存在)。 */
function importedFiles(): string[] {
  return [...source.matchAll(/@fluentui\/svg-icons\/icons\/([^'?]+)\?raw/g)].map((match) => match[1]);
}

describe('图标层', () => {
  it('每个静态导入都指向包内真实存在的 SVG', () => {
    const files = importedFiles();
    expect(files.length).toBeGreaterThan(0);
    const missing = files.filter((file) => !existsSync(join(iconsDir, file)));
    expect(missing, `以下图标文件在 @fluentui/svg-icons 里不存在:\n${missing.join('\n')}`).toEqual([]);
  });

  it('导入数量与清单一致（没有多余的导入, 也没有漏掉的图标）', () => {
    expect(importedFiles().length).toBe(ICON_NAMES.length);
  });

  it('ICON_SVG 的键与 ICON_NAMES 完全一致', () => {
    expect(Object.keys(ICON_SVG).sort()).toEqual([...ICON_NAMES].sort());
  });

  it('类型联合与运行期清单一致（两处手写容易只改一处）', () => {
    const typeStart = source.indexOf('export type IconName =');
    const typeEnd = source.indexOf(';', typeStart);
    expect(typeStart, '找不到 IconName 类型').toBeGreaterThan(-1);
    const union = [...source.slice(typeStart, typeEnd).matchAll(/'([^']+)'/g)].map((match) => match[1]);
    expect([...union].sort()).toEqual([...ICON_NAMES].sort());
  });

  it('每个图标的 SVG 里至少有一条路径', () => {
    for (const name of ICON_NAMES) {
      const svg = ICON_SVG[name];
      expect(svg.length, `${name} 的 SVG 是空的`).toBeGreaterThan(0);
      expect(svg, `${name} 的 SVG 里没有 <path>`).toContain('<path');
    }
  });

  it('没有重复的语义名', () => {
    expect(new Set(ICON_NAMES).size).toBe(ICON_NAMES.length);
  });
});
